function nowNextDateDiff(d){if(!d)return 999;return Math.round((new Date(d+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000)}
function nowNextTimeDelta(time,now=minutesFromHHMM(localTime())||0){const m=minutesFromHHMM(time);return m===null?9999:m-now}
function nowNextTaskScore(t,now){
  let score=0,dd=nowNextDateDiff(t.deadline),dateDiff=nowNextDateDiff(t.date);
  if(t.status==='doing')score+=900;
  if(dateDiff<0)score+=380+Math.min(120,Math.abs(dateDiff)*20);
  if(dd<0)score+=420+Math.min(140,Math.abs(dd)*25);else if(dd===0)score+=330;else if(dd===1)score+=170;else if(dd<=3)score+=80;
  score+=priorityRank(t.priority)*55;
  if(t.startTime){const delta=nowNextTimeDelta(t.startTime,now),dur=Math.max(15,+t.estimate||60);if(delta<=0&&delta>=-dur)score+=300;else if(delta<0)score+=180;else if(delta<=15)score+=250;else if(delta<=60)score+=130;else if(delta<=180)score+=45;else score-=Math.min(80,Math.floor(delta/30))}
  else score+=25;
  if(t.goalId)score+=12;if(t.projectId)score+=10;
  if(t.category==='research'&&researchGapDays()>=3)score+=35;const mode=activeExamMode();if(mode&&t.category===mode.category)score+=120;
  return score
}
function nowNextRoutineScore(r,now){
  let score=r.obligation==='mandatory'?210:r.obligation==='important'?100:25;
  if(r.time){const delta=nowNextTimeDelta(r.time,now),dur=Math.max(15,+r.duration||30);if(delta<=0&&delta>=-dur)score+=300;else if(delta<0)score+=165;else if(delta<=15)score+=230;else if(delta<=60)score+=110;else if(delta<=180)score+=25;else score-=70}
  return score
}
function nowNextCandidates(){
  const d=today(),now=minutesFromHHMM(localTime())||0,out=[];
  for(const t of S.tasks){
    if(t.inbox||t.status==='done'||!t.date||t.date>d||nowNextIsSnoozed('task',t.id,d))continue;
    const dep=t.dependsOn?S.tasks.find(x=>x.id===t.dependsOn):null;if(dep&&dep.status!=='done')continue;
    out.push({kind:'task',id:t.id,title:t.title,category:t.category||'personal',duration:+t.estimate||60,time:t.startTime||'',priority:t.priority||'medium',deadline:t.deadline||'',score:nowNextTaskScore(t,now)})
  }
  for(const r of dueRoutines(d)){
    if(routineActivity(r,d)||routineSkip(r,d)||nowNextIsSnoozed('routine',r.id,d))continue;
    out.push({kind:'routine',id:r.id,title:r.title,category:r.category||'personal',duration:+r.duration||30,time:r.time||'',priority:r.obligation||'important',deadline:'',score:nowNextRoutineScore(r,now)})
  }
  return out.sort((a,b)=>b.score-a.score||(a.time||'99:99').localeCompare(b.time||'99:99'))
}
function nowNextCurrentGoogle(now=minutesFromHHMM(localTime())||0){
  return S.googleEvents.filter(e=>e.date===today()&&e.time&&!e.allDay).map(e=>{const s=minutesFromHHMM(e.time),dur=Math.max(15,+e.duration||30);return{...e,_s:s,_e:(s||0)+dur}}).filter(e=>e._s!==null&&now>=e._s&&now<e._e).sort((a,b)=>a._s-b._s)[0]||null
}
function nowNextReason(x,now=minutesFromHHMM(localTime())||0){
  if(!x)return'';
  if(x.kind==='timer')return'Timer sedang berjalan sejak '+esc(x.time||localTime());
  if(x.kind==='google')return'Agenda Google Calendar sedang berlangsung'+(x.time?' sejak '+esc(x.time):'');
  if(x.kind==='routine'){const delta=nowNextTimeDelta(x.time,now);if(x.priority==='mandatory')return'Routine wajib hari ini';if(x.time&&delta<0)return'Jadwal routine sudah lewat';if(x.time&&delta<=60)return'Routine segera dimulai';return'Routine penting hari ini'}
  const t=S.tasks.find(v=>v.id===x.id),dd=nowNextDateDiff(t?.deadline),dateDiff=nowNextDateDiff(t?.date),delta=nowNextTimeDelta(t?.startTime,now);
  if(dateDiff<0)return'Task tertinggal dari hari sebelumnya';
  if(dd<0)return'Deadline sudah lewat';
  if(dd===0)return'Deadline hari ini';
  if(t?.startTime&&delta<=0)return'Jadwal mulai '+esc(t.startTime);
  if(t?.startTime&&delta<=60)return'Dijadwalkan '+esc(t.startTime);
  if(t?.priority==='high')return'High priority';
  return'Pilihan terbaik berdasarkan prioritas dan jadwal'
}
function nowNextEligibleNow(x,now=minutesFromHHMM(localTime())||0){
  if(!x)return false;
  if(x.kind==='routine'){if(!x.time)return true;return nowNextTimeDelta(x.time,now)<=30}
  const t=S.tasks.find(v=>v.id===x.id);if(!t)return false;
  if(t.status==='doing'||nowNextDateDiff(t.date)<0||nowNextDateDiff(t.deadline)<=0)return true;
  if(!t.startTime)return true;
  return nowNextTimeDelta(t.startTime,now)<=30
}
function nowNextPick(){
  const now=minutesFromHHMM(localTime())||0,timer=activeTimer(),google=nowNextCurrentGoogle(now),candidates=nowNextCandidates();
  let current=null,excludeKind='',excludeId='',nextAfter=now;
  if(timer){current={kind:'timer',id:timer.id,title:timer.title,category:timer.category||'personal',duration:Math.max(1,Math.round(timerElapsedSeconds(timer)/60)),time:timer.startTime||'',taskId:timer.taskId||null,routineId:timer.routineId||null};excludeKind=timer.taskId?'task':timer.routineId?'routine':'';excludeId=timer.taskId||timer.routineId||''}
  else if(google){current={kind:'google',id:google.id,title:google.title,category:'google',duration:Math.max(15,+google.duration||30),time:google.time||'',date:google.date};nextAfter=google._e}
  else{const eligible=candidates.filter(x=>nowNextEligibleNow(x,now));if(eligible.length){current=eligible[0];excludeKind=current.kind;excludeId=current.id}}
  const rest=candidates.filter(x=>!(x.kind===excludeKind&&x.id===excludeId));
  const future=rest.filter(x=>x.time&&(minutesFromHHMM(x.time)||0)>=nextAfter).sort((a,b)=>(minutesFromHHMM(a.time)||9999)-(minutesFromHHMM(b.time)||9999)||b.score-a.score);
  const next=future[0]||rest[0]||null;
  return{current,next,now}
}
