function automationKey(rule,target='',date=today()){return rule+'|'+target+'|'+date}
function automationSeen(key){return S.automationLog.some(x=>x.key===key)}
function recordAutomation(key,rule,summary,targetId=''){if(automationSeen(key))return;S.automationLog.push({id:uid('auto'),key,rule,summary,targetId,date:today(),at:new Date().toISOString()});S.automationLog=S.automationLog.slice(-250)}
function automationTaskExists(key){return S.tasks.some(t=>t.automationKey===key||(t.tags||[]).includes('automation:'+key))}
function createAutomationTask({key,title,date=today(),deadline='',priority='medium',category='personal',estimate=60,notes='',goalId=null,projectId=null,studyTopicId=null}){
  if(automationSeen(key)||automationTaskExists(key))return null;
  const task={id:uid('t'),title,date,deadline,status:'planned',priority,category,goalId,projectId,studyTopicId,estimate,startTime:'',notes,inbox:false,subtasks:[],tags:[],automationKey:key,autoDateManaged:true,recurrence:'none',dependsOn:null,googleTaskSync:false,googleCalendarSync:false,googleTaskId:null,googleTaskListId:null,googleCalendarEventId:null,googleOrigin:false,recurringSpawned:false};
  S.tasks.push(task);recordAutomation(key,'task',title,task.id);return task
}
function prepForCalendarEvent(e){
  const t=smartText(e.title);
  if(smartHas(t,['uts','uas','ujian','exam','final','kompetisi','competition','olimpiade','onmipa','on-mipa','tryout']))return{title:'Review materi · '+e.title,category:'study',estimate:90,priority:'high'};
  if(smartHas(t,['bimbingan','skripsi','tesis','ta','riset','research','seminar','presentasi','proposal']))return{title:'Siapkan bahan · '+e.title,category:'research',estimate:60,priority:'high'};
  if(smartHas(t,['mentoring','coaching','kelas','workshop']))return{title:'Siapkan materi · '+e.title,category:'study',estimate:45,priority:'medium'};
  return null
}
function researchGapDays(){
  const dates=S.activities.filter(x=>x.category==='research').map(x=>x.date).filter(Boolean).sort().reverse();
  if(!dates.length)return 999;
  return Math.max(0,Math.round((new Date(today()+'T12:00:00')-new Date(dates[0]+'T12:00:00'))/86400000))
}
function runAutomationEngine({silent=true}={}){
  if(!S.settings.automationEnabled)return{created:0,updated:0,messages:[]};
  let created=0,updated=0,messages=[],changed=false,d=today(),tom=add(d,1);
  if(S.settings.automationDeadline){
    for(const t of S.tasks.filter(x=>x.status!=='done'&&x.deadline&&x.deadline<=tom)){
      if(t.priority!=='high'){t.priority='high';updated++;changed=true;messages.push('Priority ↑ '+t.title)}
    }
  }
  if(S.settings.automationCalendarPrep){
    for(const e of S.googleEvents.filter(x=>x.date===tom)){
      const prep=prepForCalendarEvent(e);if(!prep)continue;
      const key=automationKey('calendar-prep',e.id||e.title,tom);
      const task=createAutomationTask({key,title:prep.title,date:d,deadline:tom,priority:prep.priority,category:prep.category,estimate:prep.estimate,notes:'Dibuat otomatis untuk agenda Google Calendar besok.'});
      if(task){created++;changed=true;messages.push(task.title)}
    }
  }
  if(S.settings.automationS2&&new Date(d+'T12:00:00').getDay()===6){
    const item=s2NextItem();
    if(item&&!s2LinkedDone(item)){
      const existing=item.taskId?S.tasks.find(t=>t.id===item.taskId):null;
      if(existing&&existing.status!=='done'){
        if(existing.date!==d){existing.date=d;existing.priority='medium';updated++;changed=true}
      }else{
        const key=automationKey('s2-weekly',item.id,d);
        const task=createAutomationTask({key,title:'S2 · '+item.title,date:d,deadline:item.due||'',priority:'medium',category:'study',estimate:60,notes:'Next step Persiapan S2 dipilih otomatis.'});
        if(task){item.taskId=task.id;created++;changed=true;messages.push(task.title)}
      }
    }
  }
  if(S.settings.automationResearchNudge&&researchGapDays()>=3){
    const activeResearch=S.projects.find(p=>p.status==='active'&&smartHas(smartText(p.area+' '+p.title),['research','riset','skripsi','paper']));
    const already=S.tasks.some(t=>t.date===d&&t.status!=='done'&&t.category==='research');
    const bucket=Math.floor(Date.parse(d+'T12:00:00')/86400000/3);
    if(!already){
      const key=automationKey('research-nudge',String(bucket),'');
      const task=createAutomationTask({key,title:activeResearch?'Lanjutkan · '+activeResearch.title:'Lanjutkan riset utama',date:d,priority:'medium',category:'research',estimate:60,projectId:activeResearch?.id||null,notes:'Dibuat otomatis karena belum ada aktivitas riset beberapa hari.'});
      if(task){created++;changed=true;messages.push(task.title)}
    }
  }
  if(changed){refreshGoalProgress();save('Automation engine')}
  if(!silent&&messages.length)toast(created+' task dibuat • '+updated+' diperbarui');
  return{created,updated,messages}
}
function busyIntervalsForDay(d=today()){
  return calendarItems(d,{includeRoutines:true}).filter(x=>x.time&&x.status!=='done').map(x=>({s:minutesFromHHMM(x.time),e:(minutesFromHHMM(x.time)||0)+Math.max(15,+x.duration||30),title:x.title,kind:x.kind})).filter(x=>x.s!==null).sort((a,b)=>a.s-b.s)
}
function freeSlotsForDay(d=today(),minMinutes=30){
  const startBase=minutesFromHHMM(S.settings.plannerStart)||480,end=minutesFromHHMM(S.settings.plannerEnd)||1320,now=d===today()?roundQuarter(minutesFromHHMM(localTime())||0):startBase,start=Math.max(startBase,now),busy=busyIntervalsForDay(d);let cursor=start,out=[];
  for(const b of busy){if(b.e<=cursor)continue;if(b.s>cursor&&b.s-cursor>=minMinutes)out.push({s:cursor,e:b.s,duration:b.s-cursor});cursor=Math.max(cursor,b.e)}
  if(end>cursor&&end-cursor>=minMinutes)out.push({s:cursor,e:end,duration:end-cursor});
  return out
}
function hhmmRange(slot){return hhmmFromMinutes(slot.s)+'–'+hhmmFromMinutes(slot.e)}

function autoPlanToday(silent=false){
  const d=today(),{fixed,floating}=plannerItems(d);
  if(!floating.length){if(!silent)toast('Semua task hari ini sudah punya jam');return 0}
  let cursor=Math.max(minutesFromHHMM(S.settings.plannerStart)||480,roundQuarter(minutesFromHHMM(localTime())||0)),end=minutesFromHHMM(S.settings.plannerEnd)||1320,planned=0;
  const busy=fixed.map(x=>({s:minutesFromHHMM(x.time),e:(minutesFromHHMM(x.time)||0)+Math.max(15,+x.duration||30)})).filter(x=>x.s!==null).sort((a,b)=>a.s-b.s);
  const insights=studyInsights(),preferred=insights.enough?insights.best.start*60:null;
  const energy=energyPlanningProfile(d),sorted=floating.slice().map(t=>{const real=S.tasks.find(x=>x.id===t.id)||t;return{...t,deadline:real.deadline||'',intelligenceScore:taskPriorityScore(real,d),energyFit:energyTaskFit(real,energy)}}).sort((a,b)=>b.intelligenceScore-a.intelligenceScore||b.energyFit-a.energyFit||(a.deadline||'9999-99-99').localeCompare(b.deadline||'9999-99-99')||(+a.duration||60)-(+b.duration||60));
  for(const t of sorted){
    const real=S.tasks.find(x=>x.id===t.id),dep=real?.dependsOn?S.tasks.find(x=>x.id===real.dependsOn):null;if(dep&&dep.status!=='done')continue;
    const dur=clamp(+t.duration||60,15,240);let candidate=cursor;
    if(preferred!==null&&['study','research','english'].includes(t.category)&&preferred>=candidate)candidate=preferred;
    let changed=true;
    while(changed){changed=false;for(const b of busy){if(candidate<b.e&&candidate+dur>b.s){candidate=b.e;changed=true;break}}}
    if(candidate+dur>end)continue;
    if(real){real.startTime=hhmmFromMinutes(candidate);real.autoScheduled=true;real.autoScheduledAt=new Date().toISOString();planned++}
    busy.push({s:candidate,e:candidate+dur});busy.sort((a,b)=>a.s-b.s);cursor=candidate+dur+15
  }
  if(planned){S.meta.lastAutoPlanDate=d;S.meta.lastAutoPlanCount=planned;save('Smart daily plan')}
  if(!silent)toast(planned?planned+' task ditempatkan ke slot kosong':'Tidak ada slot yang cukup');
  if(!silent)render();
  return planned
}
function reconcileAutoScheduledWithGoogle(d=today()){
  const events=S.googleEvents.filter(e=>e.date===d&&e.time&&!e.allDay).map(e=>({s:minutesFromHHMM(e.time),e:(minutesFromHHMM(e.time)||0)+Math.max(15,+e.duration||30)})).filter(e=>e.s!==null),tasks=S.tasks.filter(t=>t.date===d&&t.status!=='done'&&t.startTime&&t.autoScheduled);let cleared=0;
  for(const t of tasks){const s=minutesFromHHMM(t.startTime),e=(s||0)+Math.max(15,+t.estimate||60);if(s!==null&&events.some(g=>s<g.e&&e>g.s)){t.startTime='';t.autoScheduled=false;t.autoScheduledAt='';cleared++}}
  if(cleared){save('Calendar-aware replan');autoPlanToday(true)}
  return cleared
}
function maybeAutoPlanToday(){if(!S.settings.automationEnabled||!S.settings.automationAutoPlan||activeTimer())return 0;return autoPlanToday(true)}
function mergeBusyBlocks(rows=[]){
  const a=rows.filter(x=>x.s!==null&&x.e>x.s).sort((x,y)=>x.s-y.s),out=[];
  for(const b of a){const last=out.at(-1);if(last&&b.s<=last.e)last.e=Math.max(last.e,b.e);else out.push({...b})}
  return out
}
function fixedBlocksForReplan(d=today()){
  const external=calendarItems(d,{includeRoutines:true}).filter(x=>x.kind!=='task'&&x.time&&x.status!=='done').map(x=>({s:minutesFromHHMM(x.time),e:(minutesFromHHMM(x.time)||0)+Math.max(15,+x.duration||30),title:x.title,kind:x.kind})),
        manual=S.tasks.filter(t=>!t.inbox&&t.date===d&&t.status!=='done'&&t.startTime&&!t.autoScheduled).map(t=>({s:minutesFromHHMM(t.startTime),e:(minutesFromHHMM(t.startTime)||0)+Math.max(15,+t.estimate||60),title:t.title,kind:'manual-task'}));
  return mergeBusyBlocks([...external,...manual])
}
function dayLoadAnalysis(d=today()){
  const startBase=minutesFromHHMM(S.settings.plannerStart)||480,end=minutesFromHHMM(S.settings.plannerEnd)||1320,start=d===today()?Math.max(startBase,roundQuarter(minutesFromHHMM(localTime())||0)):startBase,fixed=fixedBlocksForReplan(d),fixedMinutes=mergeBusyBlocks(fixed.map(b=>({s:Math.max(start,b.s),e:Math.min(end,b.e)}))).reduce((n,b)=>n+Math.max(0,b.e-b.s),0),capacity=Math.max(0,end-start-fixedMinutes),movable=S.tasks.filter(t=>!t.inbox&&t.date===d&&t.status!=='done'&&(t.autoScheduled||!t.startTime)).filter(t=>{const dep=t.dependsOn?S.tasks.find(x=>x.id===t.dependsOn):null;return!dep||dep.status==='done'}),workload=movable.reduce((n,t)=>n+clamp(+t.estimate||60,15,240),0),overload=Math.max(0,workload-capacity);
  return{d,start,end,fixed,capacity,movable,workload,overload}
}
function nextFreeStart(busy,start,end,dur,deep=false){
  const limit=deep?Math.min(end,1230):end;let cursor=start;
  for(const b of mergeBusyBlocks(busy)){if(b.e<=cursor)continue;if(b.s>cursor&&cursor+dur<=Math.min(b.s,limit))return cursor;cursor=Math.max(cursor,b.e);if(cursor+dur>limit)return null}
  return cursor+dur<=limit?cursor:null
}
function scheduleAutoManagedOnDay(t,d,busy,earliest){
  const end=minutesFromHHMM(S.settings.plannerEnd)||1320,dur=clamp(+t.estimate||60,15,240),deep=['study','research','english'].includes(t.category)&&dur>=75,start=nextFreeStart(busy,earliest,end,dur,deep);
  if(start===null)return null;
  t.date=d;t.startTime=hhmmFromMinutes(start);t.autoScheduled=true;t.autoScheduledAt=new Date().toISOString();
  busy.push({s:start,e:start+dur,title:t.title,kind:'auto-task'});return start
}
function replanRemainingDay(silent=false){
  const d=today(),analysis=dayLoadAnalysis(d),start=analysis.start,energy=energyPlanningProfile(d),tasks=analysis.movable.slice().sort((a,b)=>taskPriorityScore(b,d)-taskPriorityScore(a,d)||energyTaskFit(b,energy)-energyTaskFit(a,energy)||(a.deadline||'9999-99-99').localeCompare(b.deadline||'9999-99-99')||(+a.estimate||60)-(+b.estimate||60)),busy=[...analysis.fixed],futureBusy=new Map();let scheduled=0,carried=0,unscheduled=0;
  for(const t of tasks)if(t.autoScheduled){t.startTime='';t.autoScheduled=false}
  for(const t of tasks){
    const placed=scheduleAutoManagedOnDay(t,d,busy,start);
    if(placed!==null){scheduled++;continue}
    const mayMoveDate=!!t.autoDateManaged||!!t.automationKey;
    if(mayMoveDate){
      let moved=false;
      for(let offset=1;offset<=3&&!moved;offset++){
        const nd=add(d,offset);if(t.deadline&&nd>t.deadline)break;
        if(!futureBusy.has(nd)){
          const existing=calendarItems(nd,{includeRoutines:true}).filter(x=>x.time&&x.status!=='done').map(x=>({s:minutesFromHHMM(x.time),e:(minutesFromHHMM(x.time)||0)+Math.max(15,+x.duration||30),title:x.title,kind:x.kind})).filter(x=>x.s!==null);
          futureBusy.set(nd,mergeBusyBlocks(existing))
        }
        const nb=futureBusy.get(nd),ns=minutesFromHHMM(S.settings.plannerStart)||480;
        if(scheduleAutoManagedOnDay(t,nd,nb,ns)!==null){t.autoDateManaged=true;carried++;moved=true}
      }
      if(moved)continue
    }
    t.startTime='';t.autoScheduled=false;unscheduled++
  }
  if(tasks.length)save('Smart reschedule v2');
  if(!silent){toast('Rebalanced · '+scheduled+' scheduled'+(carried?' · '+carried+' carried forward':'')+(unscheduled?' · '+unscheduled+' need review':''));render()}
  return{scheduled,carried,unscheduled,overload:analysis.overload}
}
function smartPlannerCard(){const d=today(),items=calendarItems(d,{includeRoutines:true}).filter(x=>x.status!=='done'),unscheduled=S.tasks.filter(t=>!t.inbox&&t.date===d&&t.status!=='done'&&!t.startTime).length,load=dayLoadAnalysis(d);return'<article class="card smart-planner-card" data-widget="planner"><div class="card-head"><div><h2>Smart Reschedule</h2><p>Manual times stay fixed. Autopilot tasks move only around real free space.</p></div><span class="pill '+(load.overload?'orange':'green')+'">'+(load.overload?'OVERLOAD '+mins(load.overload):'BALANCED')+'</span></div><div class="planner-capacity"><div><span>Movable workload</span><b>'+mins(load.workload)+'</b></div><div><span>Free capacity</span><b>'+mins(load.capacity)+'</b></div><div><span>Manual / fixed</span><b>'+load.fixed.length+' blocks</b></div></div><div class="planner-preview">'+(items.length?items.slice(0,6).map(x=>'<div class="planner-row"><time>'+esc(x.time||'—')+'</time><span>'+esc(x.title)+'</span><b>'+cat(x.category)+'</b></div>').join(''):'<div class="empty empty-compact">No agenda yet.</div>')+'</div><div class="button-row" style="margin-top:12px"><button class="btn btn-primary" data-act="replanDay">Rebalance Safely</button>'+(unscheduled?'<button class="btn btn-secondary" data-act="autoPlanToday">Place '+unscheduled+' unscheduled</button>':'')+'</div>'+(load.overload?'<div class="callout planner-overload-note">Today is overloaded by <b>'+mins(load.overload)+'</b>. Only automation-managed dates may be carried forward automatically.</div>':'')+'</article>'}
function roundQuarter(v){return Math.ceil(v/15)*15}
function maybeAutoReplan(){if(!S.settings.autoReplan||activeTimer())return;const m=minutesFromHHMM(localTime())||0,key=today()+'-'+Math.floor(m/30),load=dayLoadAnalysis(today()),late=S.tasks.some(t=>t.date===today()&&t.status!=='done'&&t.autoScheduled&&t.startTime&&(minutesFromHHMM(t.startTime)||0)<m);if((late||load.overload>0)&&S.meta.lastAutoReplanKey!==key){S.meta.lastAutoReplanKey=key;replanRemainingDay(true)}}

/* ===== Desca OS v50 · Intelligence Suite ===== */
function energyPlanningProfile(d=today()){
  const rows=(S.healthLogs||[]).filter(x=>x.date<=d&&x.date>=add(d,-3)).slice().sort((a,b)=>(b.date||'').localeCompare(a.date||'')),h=rows[0]||null;
  let score=h&&+h.energy?clamp(Math.round(+h.energy*20),20,100):60;
  if(h&&+h.sleep>0&&+h.sleep<6.5)score=Math.max(25,score-15);
  if(h&&+h.sleep>=7.5)score=Math.min(100,score+5);
  const level=score>=76?'High':score<=45?'Low':'Steady',label=level==='High'?'Deep-work ready':level==='Low'?'Keep it lighter':'Balanced capacity';
  return{score,level,label,health:h}
}
function taskPriorityParts(t,d=today()){
  if(!t)return{score:0,deadline:0,importance:0,impact:0,momentum:0,effort:0,dependency:0};
  let deadline=0,importance=t.priority==='high'?25:t.priority==='medium'?16:8,impact=(t.goalId?10:0)+(t.projectId?8:0)+(t.academicAssessmentId?10:0),momentum=0,effort=0,dependency=0;
  const due=t.deadline||t.date||'';
  if(due){const days=Math.round((new Date(due+'T12:00:00')-new Date(d+'T12:00:00'))/86400000);deadline=days<0?35:days===0?32:days<=2?27:days<=7?20:days<=14?12:5}
  if(t.date&&t.date<d&&t.status!=='done')momentum+=10;if(t.status==='doing')momentum+=8;
  const est=clamp(+t.estimate||45,5,480);effort=est<=45?8:est<=90?5:2;
  const dep=t.dependsOn?S.tasks.find(x=>x.id===t.dependsOn):null;if(dep&&dep.status!=='done')dependency=-25;
  return{deadline,importance,impact,momentum,effort,dependency,score:clamp(deadline+importance+impact+momentum+effort+dependency,0,100)}
}
function taskPriorityScore(t,d=today()){return taskPriorityParts(t,d).score}
function priorityScoreBadge(t){
  const p=taskPriorityParts(t),tone=p.score>=75?'hot':p.score>=50?'warm':'calm',tip='Deadline '+p.deadline+' · Priority '+p.importance+' · Impact '+p.impact+' · Momentum '+p.momentum+' · Effort '+p.effort+(p.dependency?' · Dependency '+p.dependency:'');
  return'<span class="priority-score '+tone+'" title="'+esc(tip)+'">P'+p.score+'</span>'
}
function energyTaskFit(t,profile=energyPlanningProfile()){
  const deep=['study','research','project'].includes(t?.category)&&(+t?.estimate||0)>=60,light=['personal','finance','dmath'].includes(t?.category)||(+t?.estimate||0)<=45;
  if(profile.level==='High')return deep?14:light?2:6;if(profile.level==='Low')return light?14:deep?-12:4;return deep?7:6
}
function priorityQueueCard(rows=S.tasks.filter(t=>!t.inbox&&t.status!=='done')){
  const top=rows.slice().sort((a,b)=>taskPriorityScore(b)-taskPriorityScore(a)||(+a.estimate||45)-(+b.estimate||45)).slice(0,5);
  return'<article class="card priority-intelligence-card"><div class="card-head"><div><div class="eyebrow">PRIORITY ENGINE</div><h2>What deserves attention first</h2><p>Score = deadline + stated priority + goal/project impact + momentum + effort + dependency.</p></div><span class="pill blue">'+top.length+' ranked</span></div><div class="priority-intelligence-list">'+(top.length?top.map((t,i)=>'<div class="priority-intelligence-row"><strong>0'+(i+1)+'</strong><div><b>'+esc(t.title)+'</b><small>'+cat(t.category)+' • '+mins(t.estimate)+' • '+(t.deadline?'deadline '+fmt(t.deadline,{day:'numeric',month:'short'}):'no deadline')+'</small></div>'+priorityScoreBadge(t)+'<button class="mini-btn" data-act="startTaskTimer" data-id="'+t.id+'">Start</button></div>').join(''):'<div class="empty empty-compact">No active tasks to rank.</div>')+'</div></article>'
}
function scheduleConflictData(d=today()){
  const items=calendarItems(d,{includeRoutines:true}).filter(x=>x.status!=='done'&&x.status!=='skipped'&&x.time).map(x=>{const s=minutesFromHHMM(x.time),dur=Math.max(15,+x.duration||30);return{...x,s,e:(s||0)+dur}}).filter(x=>x.s!==null).sort((a,b)=>a.s-b.s),conflicts=[];
  for(let i=0;i<items.length;i++)for(let j=i+1;j<items.length;j++){const a=items[i],b=items[j];if(b.s>=a.e)break;if(a.s<b.e&&b.s<a.e){const ta=a.kind==='task'?S.tasks.find(x=>x.id===a.id):null,tb=b.kind==='task'?S.tasks.find(x=>x.id===b.id):null;conflicts.push({a,b,movableIds:[ta?.autoScheduled?a.id:null,tb?.autoScheduled?b.id:null].filter(Boolean)})}}
  return conflicts
}
function conflictCenterCard(d=today()){
  const rows=scheduleConflictData(d);if(!rows.length)return'<article class="card conflict-center-card clean"><div><span class="conflict-icon">✓</span><div><div class="eyebrow">SCHEDULE CHECK</div><b>No conflicts detected</b><small>Timed tasks, routines, and synced calendar events do not overlap.</small></div></div></article>';
  const auto=rows.reduce((s,x)=>s+x.movableIds.length,0);
  return'<article class="card conflict-center-card"><div class="card-head"><div><div class="eyebrow">SMART CONFLICT DETECTOR</div><h2>'+rows.length+' schedule conflict'+(rows.length>1?'s':'')+'</h2><p>'+rows.slice(0,3).map(x=>esc((x.a.time||'')+' '+x.a.title+' ↔ '+x.b.title)).join(' • ')+'</p></div><span class="pill red">'+rows.length+' CONFLICT</span></div><div class="button-row">'+(auto?'<button class="btn btn-primary" data-act="resolveScheduleConflicts">Resolve Automatically</button>':'')+'<button class="btn btn-secondary" data-route="calendar">Review Calendar</button></div>'+(auto?'':'<div class="callout">Only manually fixed items overlap, so Desca OS will not move them without your decision.</div>')+'</article>'
}
function resolveScheduleConflicts(){
  const rows=scheduleConflictData(),ids=[...new Set(rows.flatMap(x=>x.movableIds))];for(const id of ids){const t=S.tasks.find(x=>x.id===id);if(t){t.startTime='';t.autoScheduled=false;t.autoScheduledAt=''}}
  if(ids.length){replanRemainingDay(true);save('Resolve schedule conflicts')}const remaining=scheduleConflictData();toast(ids.length?('Resolved '+ids.length+' auto-planned item'+(ids.length>1?'s':'')+(remaining.length?' · '+remaining.length+' manual conflict remains':'')):'No auto-planned conflict can be moved');render()
}
