function runningPage(){const runs=S.runs.slice().sort((a,b)=>(b.date+(b.startTime||'')).localeCompare(a.date+(a.startTime||''))),weekKm=runWeekDistance(),goalKm=Math.max(1,+S.settings.runningWeeklyGoalKm||20),weekRuns=runs.filter(x=>x.date>=runWeekStart()),weekTime=weekRuns.reduce((n,x)=>n+(+x.durationSec||0),0),weekLoad=runningLoad(7),load28=runningLoad(28),recent=runs.slice(0,12),weekly=runWeeklySeries(8),avgPace=weekRuns.length?Math.round(weekRuns.reduce((n,x)=>n+runPaceSec(x),0)/weekRuns.length):0,avgHR=weekRuns.filter(x=>x.avgHR).length?Math.round(weekRuns.filter(x=>x.avgHR).reduce((n,x)=>n+(+x.avgHR||0),0)/weekRuns.filter(x=>x.avgHR).length):0,totalKm=runs.reduce((n,x)=>n+(+x.distanceKm||0),0),r28=runs.filter(x=>x.date>=add(today(),-27)),cad28=r28.filter(x=>x.cadence).length?Math.round(r28.filter(x=>x.cadence).reduce((n,x)=>n+(+x.cadence||0),0)/r28.filter(x=>x.cadence).length):0,elev28=Math.round(r28.reduce((n,x)=>n+(+x.elevationGain||0),0));$('#page').innerHTML=head('Running','Track pace, heart rate, cadence, elevation, splits, training load, dan mileage secara lengkap.','<button class="btn btn-secondary" data-act="runningSettings">⚙ Settings</button><button class="btn btn-primary" data-act="newRun">+ Log Run</button>')+'<section class="running-hero"><div><div class="eyebrow">RUNNING DASHBOARD</div><h1>'+weekKm.toFixed(1)+' / '+goalKm.toFixed(1)+' km minggu ini</h1><p>'+weekRuns.length+' sesi • '+runDurationText(weekTime)+' waktu lari • '+runningActiveWeekStreak()+' active-week streak</p>'+prog(weekKm/goalKm*100)+'</div><div class="running-hero-pace"><span>Avg Pace Minggu Ini</span><b>'+runPaceText(avgPace)+'</b><small>'+(avgHR?avgHR+' bpm avg HR':'Belum ada HR')+'</small></div></section><section class="grid metric-grid compact-metrics">'+metric('Weekly Distance',weekKm.toFixed(1)+' km',Math.round(weekKm/goalKm*100)+'% target','↗')+metric('Run Time',runDurationText(weekTime),weekRuns.length+' sesi','◷')+metric('sRPE Load',num(weekLoad),'7 hari • 28D '+num(load28),'▤')+metric('Total Distance',totalKm.toFixed(1)+' km',runs.length+' sesi tercatat','◎')+metric('Active Weeks',runningActiveWeekStreak(),'Streak minggu dengan lari','🔥')+metric('Avg Cadence',cad28?cad28+' spm':'—','28 hari','⌁')+metric('Elevation',elev28?num(elev28)+' m':'—','Gain 28 hari','△')+'</section>'+consistencyCompact('fitness')+'<div class="grid two-col"><article class="card chart-card"><div class="card-head"><div><h2>Weekly Mileage</h2><p>Volume jarak 8 minggu terakhir.</p></div></div>'+lineChart(weekly.map(x=>x.km),weekly.map(x=>x.label),{suffix:'km'})+'</article><article class="card"><div class="card-head"><div><h2>Heart Rate Zones</h2><p>Distribusi durasi berdasarkan average HR sesi.</p></div><span class="pill blue">Max '+S.settings.runningMaxHR+' bpm</span></div>'+runZoneDistribution(28)+'</article></div><div class="grid two-col section-gap"><article class="card"><div class="card-head"><div><h2>Recent Pace Trend</h2><p>Semakin pendek pace, semakin cepat.</p></div></div>'+runningRecentTrend()+'</article><article class="card"><div class="card-head"><div><h2>Best Recorded Sessions</h2><p>Ringkasan terbaik dari sesi yang benar-benar dicatat.</p></div></div>'+runningBestCards()+'</article></div><article class="card section-gap"><div class="card-head"><div><h2>Run History</h2><p>Semua metrik per sesi, termasuk HR, cadence, elevation, dan splits.</p></div><button class="mini-btn" data-act="newRun">+ Run</button></div><div class="run-history">'+(recent.length?recent.map(runCard).join(''):'<div class="empty empty-state-large"><span class="empty-icon">↗</span><b>Belum ada sesi lari.</b><small>Log lari pertama untuk mulai melihat pace, heart rate, mileage, dan trend latihan.</small><button class="btn btn-primary" data-act="newRun">Log Run Pertama</button></div>')+'</div>'+(runs.length>recent.length?'<div class="item-meta" style="margin-top:12px">Menampilkan 12 sesi terbaru dari '+runs.length+' total.</div>':'')+'</article>'}
