function ensureFocusOverlay(){let z=$('#focusZen');if(z)return z;z=document.createElement('section');z.id='focusZen';z.className='focus-zen';z.hidden=true;z.setAttribute('aria-live','polite');z.innerHTML='<div class="zen-top"><div class="zen-brand"><span class="brand-mark">D</span><div><b>Desca OS</b><small>Focus Mode</small></div></div><button class="zen-minimize" data-act="minimizeFocus" type="button">Minimize</button></div><div class="zen-center"><div class="zen-phase" id="zenPhase">FOKUS</div><div class="zen-session" id="zenSession">Belajar Fokus</div><div class="zen-clock-wrap"><div class="zen-ring" id="zenRing"><div class="zen-clock" id="zenClock">25:00</div></div></div><div class="zen-meta"><span id="zenCategory">Study</span><span>•</span><span id="zenCycle">Sesi 1 / 4</span></div><div class="zen-actions"><button class="zen-main" data-act="focus" type="button" id="zenPlay">Pause</button><button class="zen-secondary" data-act="resetFocus" type="button">Akhiri sesi</button><button class="zen-secondary" data-act="skipBreak" type="button" id="zenSkip">Lewati istirahat</button></div><div class="zen-tip">Space untuk pause/resume • Esc untuk minimize</div></div>';document.body.append(z);let d=document.createElement('button');d.id='focusDock';d.className='focus-dock';d.hidden=true;d.type='button';d.dataset.act='restoreFocus';d.innerHTML='<span class="focus-dock-dot"></span><span><b id="dockClock">25:00</b><small id="dockLabel">Focus Mode</small></span><span>↗</span>';document.body.append(d);return z}
function tryNativeFullscreen(){const el=document.documentElement;if(!document.fullscreenElement&&el.requestFullscreen)el.requestFullscreen().catch(()=>{})}
function exitNativeFullscreen(){if(document.fullscreenElement&&document.exitFullscreen)document.exitFullscreen().catch(()=>{})}
function updateFocusOverlay(){const z=ensureFocusOverlay(),dock=$('#focusDock'),cycles=clamp(+S.settings.pomodoroCycles||4,1,12),pct=clamp((1-focus.left/Math.max(1,focus.total))*100,0,100),active=!!(focus.startedAt||focus.running||focus.phase!=='focus');z.hidden=!focus.zen;dock.hidden=focus.zen||!active;document.body.classList.toggle('focus-zen-active',focus.zen);$('#zenPhase').textContent=focusPhaseLabel();$('#zenSession').textContent=focus.phase==='focus'?(focus.label||'Belajar Fokus'):'Pulihkan energi';$('#zenClock').textContent=focusTimeText();$('#zenCategory').textContent=cat(focus.category);$('#zenCycle').textContent='Sesi '+focus.cycle+' / '+cycles;$('#zenRing').style.setProperty('--zen-progress',pct+'%');$('#zenPlay').textContent=focus.running?'Pause':focus.phase==='focus'?'Lanjut Fokus':'Mulai Istirahat';$('#zenSkip').hidden=focus.phase==='focus';$('#dockClock').textContent=focusTimeText();$('#dockLabel').textContent=focusPhaseLabel()+' • '+(focus.phase==='focus'?(focus.label||cat(focus.category)):'Break')}
