function buildWeekPlan(){
  const candidates=S.tasks.filter(t=>t.status!=='done'&&!t.inbox&&(t.autoDateManaged||!t.date||!t.startTime)).filter(t=>{const dep=t.dependsOn?S.tasks.find(x=>x.id===t.dependsOn):null;return!dep||dep.status==='done'}).sort((a,b)=>(a.deadline||'9999-99-99').localeCompare(b.deadline||'9999-99-99')||priorityRank(b.priority)-priorityRank(a.priority));
  let placed=0;const busyByDay=new Map();
  for(let off=0;off<7;off++){const d=add(today(),off),existing=calendarItems(d,{includeRoutines:true}).filter(x=>x.time&&x.status!=='done').map(x=>({s:minutesFromHHMM(x.time),e:(minutesFromHHMM(x.time)||0)+Math.max(15,+x.duration||30)}));busyByDay.set(d,mergeBusyBlocks(existing))}
  for(const t of candidates){let done=false;for(let off=0;off<7&&!done;off++){const d=add(today(),off);if(t.deadline&&d>t.deadline)break;const busy=busyByDay.get(d),start=off===0?Math.max(roundQuarter(minutesFromHHMM(localTime())||0),minutesFromHHMM(S.settings.plannerStart)||480):minutesFromHHMM(S.settings.plannerStart)||480;if(scheduleAutoManagedOnDay(t,d,busy,start)!==null){t.autoDateManaged=true;placed++;done=true}}}
  save('Build my week');close();toast('Week planned · '+placed+' task(s) placed');render()
}
