function seasonHistoryData(){
  const months=[...new Set([...S.activities.map(a=>(a.date||'').slice(0,7)),...S.tasks.map(t=>(t.date||'').slice(0,7)),today().slice(0,7)].filter(x=>/^\d{4}-\d{2}$/.test(x)))].sort().reverse();
  return months.slice(0,12).map(seasonScoreForMonth)
}
