function s2DocumentForm(){return'<form id="s2DocumentForm"><div class="form-grid"><div class="field full"><label>Nama berkas</label><input name="title" required placeholder="Contoh: Sertifikat TOEFL"></div><div class="field"><label>Kelompok</label><select name="group">'+['Identitas','Akademik','Aplikasi','Riset','Rekomendasi','Bahasa','Beasiswa','Lainnya'].map(x=>'<option>'+x+'</option>').join('')+'</select></div><div class="field"><label>Target tanggal</label><input name="due" type="date" value="'+today()+'"></div></div><button class="btn btn-primary" style="margin-top:14px;width:100%">Tambah Berkas</button></form>'}
