function syncS2Tasks(){let made=0;for(const item of S.s2Prep.checklist.filter(x=>!s2ItemDone(x))){if(item.taskId&&S.tasks.some(t=>t.id===item.taskId))continue;const id=uid('t');S.tasks.push({id,title:'S2 · '+item.title,date:item.due||today(),deadline:item.due||'',status:'planned',priority:'medium',category:'study',goalId:null,projectId:null,studyTopicId:null,estimate:60,startTime:'',notes:'Dibuat otomatis dari Persiapan S2',inbox:false,subtasks:[],tags:['s2','preparation'],recurrence:'none',dependsOn:null,googleTaskSync:false,googleCalendarSync:false,googleTaskId:null,googleTaskListId:null,googleCalendarEventId:null,googleOrigin:false,recurringSpawned:false});item.taskId=id;made++}save('Sync S2 checklist to tasks');toast(made?made+' task S2 dibuat otomatis':'Checklist S2 sudah tersinkron');render()}
function goalsPage(){refreshGoalProgress();const active=S.goals.filter(g=>g.status!=='completed').length,avg=S.goals.length?Math.round(S.goals.reduce((a,g)=>a+goalComputedProgress(g),0)/S.goals.length):0;$('#page').innerHTML=head('Goals','Goal → milestone → task → activity. Progress bisa dihitung otomatis dari pekerjaan nyata.','<button class="btn btn-primary" data-act="newGoal">+ Goal</button>')+'<section class="grid metric-grid compact-metrics">'+metric('Active Goals',active,'Sedang berjalan','◎')+metric('Avg Progress',avg+'%','Semua goal','↗')+metric('Completed',S.goals.filter(g=>g.status==='completed').length,'Goal selesai','✓')+metric('Linked Tasks',S.tasks.filter(t=>t.goalId).length,'Task terhubung','▦')+metric('Linked Activity',S.activities.filter(a=>a.goalId).length,'Aktivitas terhubung','✦')+'</section>'+s2PrepCard()+'<div class="grid goals-layout"><div class="grid">'+(S.goals.length?S.goals.map(g=>{const gp=goalComputedProgress(g),linked=S.tasks.filter(t=>t.goalId===g.id),md=g.milestoneDone||[],fc=goalForecast(g);return'<article class="card goal-detail"><div class="card-head"><div><div class="goal-status-row"><span class="pill '+(g.status==='completed'?'green':g.status==='paused'?'orange':'blue')+'">'+(g.status||'active')+'</span><span class="goal-deadline">'+fmt(g.deadline,{day:'numeric',month:'short',year:'numeric'})+'</span><span class="pill">'+(g.autoProgress===false?'MANUAL':'AUTO')+'</span></div><h2>'+esc(g.title)+'</h2><p>'+esc(g.area||'Goal')+' • '+linked.filter(t=>t.status==='done').length+'/'+linked.length+' linked task selesai</p></div><div class="button-row compact"><button class="mini-btn" data-act="inspectRelation" data-type="goal" data-id="'+g.id+'">Relations</button><button class="mini-btn" data-act="decomposeGoal" data-id="'+g.id+'">Generate Plan</button><button class="mini-btn" data-act="editGoal" data-id="'+g.id+'">Edit</button>'+(g.status==='completed'?'<button class="mini-btn" data-act="archiveEntity" data-type="goal" data-id="'+g.id+'" data-label="'+esc(g.title)+'">Archive</button>':'')+'</div></div><div class="goal-progress hero-progress">'+prog(gp)+'<b>'+gp+'%</b></div><div class="goal-forecast-detail '+(fc.status==='At Risk'?'risk':fc.status==='On Track'?'good':'')+'"><span>FORECAST</span><b>'+esc(fc.status)+'</b><small>'+esc(fc.message)+'</small></div><div class="simple-list milestone-list" style="margin-top:14px">'+((g.milestones||[]).length?(g.milestones||[]).map((m,i)=>'<button class="list-row milestone-toggle '+(md.includes(i)?'done':'')+'" data-act="toggleMilestone" data-id="'+g.id+'" data-index="'+i+'"><span class="milestone-check">'+(md.includes(i)?'✓':'○')+'</span><div class="item-title">'+esc(m)+'</div></button>').join(''):'<div class="empty empty-compact">Belum ada milestone.</div>')+'</div>'+(linked.length?'<div class="goal-linked-tasks"><div class="item-meta" style="margin:14px 0 8px">LINKED TASKS</div>'+linked.slice(0,6).map(task).join('')+'</div>':'')+'</article>'}).join(''):'<div class="empty empty-state-large"><span class="empty-icon">◎</span><b>Belum ada goal.</b><small>Buat satu tujuan yang benar-benar ingin kamu dorong bulan ini.</small><button class="btn btn-primary" data-act="newGoal">Buat Goal Pertama</button></div>')+'</div><aside class="card goal-guide"><div class="card-head"><div><h2>Goal → Action</h2><p>Progress mengikuti pekerjaan nyata.</p></div></div><div class="goal-flow"><span>Goal</span><i>→</i><span>Milestone</span><i>→</i><span>Task</span><i>→</i><span>Activity</span><i>→</i><span>Review</span></div><div class="callout" style="margin-top:16px">Mode Auto menghitung rata-rata completion milestone dan linked task. Jika belum ada keduanya, progress manual tetap dipakai.</div></aside></div>'}
