function academicSemesterForm(x={}){return'<form id="academicSemesterForm"><div class="form-grid"><div class="field full"><label>Semester</label><input name="name" required value="'+esc(x.name||'')+'" placeholder="Semester 7 · 2026/2027"></div><div class="field"><label>Start</label><input name="start" type="date" value="'+esc(x.start||today())+'"></div><div class="field"><label>End</label><input name="end" type="date" value="'+esc(x.end||add(today(),120))+'"></div><div class="field"><label>Status</label><select name="status">'+['active','planned','completed'].map(v=>'<option '+((x.status||'active')===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div></div><input type="hidden" name="id" value="'+(x.id||'')+'"><button class="btn btn-primary" style="margin-top:12px;width:100%">Save Semester</button></form>'}
