function projectHealth(p){
  const linked=S.tasks.filter(t=>t.projectId===p.id),overdue=linked.filter(t=>t.status!=='done'&&t.deadline&&t.deadline<today()).length,acts=S.activities.filter(a=>a.projectId===p.id).map(a=>a.date).filter(Boolean).sort(),last=acts.at(-1)||p.startDate||p.createdAt?.slice(0,10)||'',inactive=last?Math.max(0,Math.round((new Date(today()+'T12:00:00')-new Date(last+'T12:00:00'))/86400000)):999,pct=projectProgress(p),deadlineDays=p.deadline?Math.round((new Date(p.deadline+'T12:00:00')-new Date(today()+'T12:00:00'))/86400000):999;
  let score=100;score-=Math.min(35,overdue*12);score-=inactive>=14?35:inactive>=7?22:inactive>=4?10:0;if(deadlineDays<0&&pct<100)score-=35;else if(deadlineDays<=7&&pct<70)score-=20;if(!p.nextAction)score-=10;score=clamp(score,0,100);
  const status=p.status==='completed'?'Completed':score>=75?'On Track':score>=45?'At Risk':'Stalled';
  return{score,status,overdue,inactive,last,deadlineDays}
}
