function paperAuthorParts(p){const a=String(p.authors||'').split(',').map(x=>x.trim()).filter(Boolean);return a.length?a:['Unknown Author']}
function citationIEEE(p){const authors=paperAuthorParts(p).join(', '),year=p.year||'n.d.',doi=normalizeDoi(p.doi||'');return authors+', “'+p.title+'”, '+year+(doi?', doi: '+doi:'')+'.'}
function citationAPA(p){const authors=paperAuthorParts(p).join(', '),year=p.year||'n.d.',doi=normalizeDoi(p.doi||'');return authors+' ('+year+'). '+p.title+'.'+(doi?' https://doi.org/'+doi:'')}
function bibtexKey(p){const first=(paperAuthorParts(p)[0]||'paper').split(/\s+/).at(-1).replace(/[^A-Za-z0-9]/g,'')||'paper';return first+(p.year||'')+(p.title||'paper').split(/\s+/)[0].replace(/[^A-Za-z0-9]/g,'')}
function citationBibTeX(p){const doi=normalizeDoi(p.doi||''),authors=paperAuthorParts(p).join(' and ');return '@article{'+bibtexKey(p)+',\n  title={'+p.title+'},\n  author={'+authors+'},\n  year={'+(p.year||'')+'}'+(doi?',\n  doi={'+doi+'}':'')+'\n}'}
function paperCitation(p,type='ieee'){return type==='apa'?citationAPA(p):type==='bibtex'?citationBibTeX(p):citationIEEE(p)}
function openCitationManager(id){const p=S.researchPapers.find(x=>x.id===id);if(!p)return;open('<div class="modal-head"><div><div class="eyebrow">CITATION MANAGER</div><h2 id="modalTitle">'+esc(p.title)+'</h2></div><button class="icon-btn" data-act="close">×</button></div><div class="citation-stack">'+[['ieee','IEEE'],['apa','APA'],['bibtex','BibTeX']].map(([k,label])=>'<section class="citation-box"><div><b>'+label+'</b><button class="mini-btn" data-act="copyCitation" data-id="'+p.id+'" data-citation="'+k+'">Copy '+label+'</button></div><pre>'+esc(paperCitation(p,k))+'</pre></section>').join('')+'</div>')}
async function openPaperReader(id){
  const p=S.researchPapers.find(x=>x.id===id);if(!p)return;
  let row=await paperFileGet(id);if(!row?.blob&&p.driveFileId&&googleReady()){try{await restorePaperPDF(id,true);row=await paperFileGet(id)}catch{}}
  if(!row?.blob){toast('PDF belum tersedia di perangkat ini');return}
  p.status=p.status==='to-read'?'reading':p.status;p.lastOpenedAt=new Date().toISOString();save('Open paper reader');
  const url=URL.createObjectURL(row.blob);
  open('<div class="modal-head paper-reader-head"><div><div class="eyebrow">PAPER READER</div><h2 id="modalTitle">'+esc(p.title)+'</h2></div><div class="button-row compact"><button class="mini-btn" data-act="openCitationManager" data-id="'+p.id+'">Cite</button><button class="mini-btn" data-act="noteFromPaper" data-id="'+p.id+'">Create Note</button><button class="icon-btn" data-act="close">×</button></div></div><div class="paper-reader-layout"><iframe class="paper-reader-frame" src="'+url+'#page='+(Math.max(1,+p.lastPage||1))+'" data-object-url="'+url+'" title="'+esc(p.title)+'"></iframe><form id="paperReaderForm" class="paper-reader-side"><input type="hidden" name="id" value="'+p.id+'"><div class="field"><label>Reading progress</label><div class="paper-reader-progress"><input name="readProgress" type="range" min="0" max="100" value="'+clamp(+p.readProgress||0,0,100)+'"><b>'+clamp(+p.readProgress||0,0,100)+'%</b></div></div><div class="field"><label>Last page</label><input name="lastPage" type="number" min="0" value="'+Math.max(0,+p.lastPage||0)+'"></div><div class="field"><label>Relevance rating</label><select name="rating"><option value="0">Not rated</option>'+[1,2,3,4,5].map(v=>'<option value="'+v+'" '+(+p.rating===v?'selected':'')+'>'+v+' / 5</option>').join('')+'</select></div><div class="field"><label>General notes</label><textarea name="annotations" rows="5" placeholder="Paper-level notes...">'+esc(p.annotations||'')+'</textarea></div>'+paperMarksHtml(p)+'<button class="btn btn-primary">Save Reading Progress</button></form></div>')
}
function paperMarksHtml(p){
  const rows=(p.paperMarks||[]).slice().sort((a,b)=>(+a.page||0)-(+b.page||0));
  return'<div class="paper-marks"><div class="paper-marks-head"><b>Page-linked annotations</b><span>'+rows.length+'</span></div><div class="paper-marks-list">'+(rows.length?rows.map(m=>'<div class="paper-mark '+esc(m.color||'blue')+'"><button data-act="goPaperMark" data-id="'+p.id+'" data-mark="'+m.id+'"><b>p. '+m.page+'</b><span>'+esc(m.type||'note')+'</span></button><div><small>'+esc(m.quote||m.text||'Annotation')+'</small>'+(m.text&&m.quote?'<p>'+esc(m.text)+'</p>':'')+'</div><button class="icon-btn tiny" data-act="removePaperMark" data-id="'+p.id+'" data-mark="'+m.id+'">×</button></div>').join(''):'<div class="empty empty-compact">No page annotations yet.</div>')+'</div><div class="paper-mark-add"><input id="paperMarkPage" type="number" min="1" value="'+Math.max(1,+p.lastPage||1)+'" placeholder="Page"><select id="paperMarkType"><option value="highlight">Highlight</option><option value="bookmark">Bookmark</option><option value="note">Note</option><option value="quote">Quote</option></select><select id="paperMarkColor"><option value="yellow">Yellow</option><option value="blue">Blue</option><option value="green">Green</option><option value="purple">Purple</option></select><input id="paperMarkQuote" placeholder="Quoted text / label"><textarea id="paperMarkText" rows="2" placeholder="Annotation"></textarea><button type="button" class="mini-btn" data-act="addPaperMark" data-id="'+p.id+'">Add Annotation</button></div></div>'
}
function addPaperMark(id){
  const p=S.researchPapers.find(x=>x.id===id);if(!p)return;const page=Math.max(1,+$('#paperMarkPage')?.value||1),type=$('#paperMarkType')?.value||'note',color=$('#paperMarkColor')?.value||'yellow',quote=$('#paperMarkQuote')?.value.trim()||'',text=$('#paperMarkText')?.value.trim()||'';if(!quote&&!text){toast('Isi quote atau annotation');return}
  p.paperMarks=p.paperMarks||[];p.paperMarks.push({id:uid('mark'),page,type,color,quote,text,createdAt:new Date().toISOString()});p.lastPage=page;save('Paper annotation');openPaperReader(id)
}
function removePaperMark(id,markId){const p=S.researchPapers.find(x=>x.id===id);if(!p)return;p.paperMarks=(p.paperMarks||[]).filter(m=>m.id!==markId);save('Remove paper annotation');openPaperReader(id)}
function goPaperMark(id,markId){const p=S.researchPapers.find(x=>x.id===id),m=p?.paperMarks?.find(x=>x.id===markId),frame=$('.paper-reader-frame');if(!p||!m||!frame)return;const base=(frame.dataset.objectUrl||frame.src.split('#')[0]);frame.src=base+'#page='+m.page;p.lastPage=m.page;save('Jump paper annotation')}
function chooseSmartPaperPDF(){let input=document.getElementById('smartPaperImportFile');if(!input){input=document.createElement('input');input.id='smartPaperImportFile';input.type='file';input.accept='application/pdf,.pdf';input.hidden=true;document.body.appendChild(input)}input.value='';input.click()}
function noteFromPaper(id){const p=S.researchPapers.find(x=>x.id===id);if(!p)return;close();openResearchNote({paperId:p.id,projectId:p.projectId||'',type:'quote',date:today(),title:'Notes · '+p.title,text:p.annotations||''})}
function readingQueue(){
  return S.researchPapers.filter(p=>p.status!=='read').map(p=>{const project=S.projects.find(x=>x.id===p.projectId),inactive=p.lastOpenedAt?Math.max(0,Math.round((Date.now()-Date.parse(p.lastOpenedAt))/86400000)):30;let score=p.status==='reading'?70:p.status==='key'?85:45;if(project?.status==='active')score+=20;if(p.pdfName)score+=10;score+=Math.min(20,inactive);score-=Math.round((+p.readProgress||0)*.25);return{p,score}}).sort((a,b)=>b.score-a.score).slice(0,5)
}
function readingQueueCard(){const q=readingQueue();return'<article class="card reading-queue-card"><div class="card-head"><div><div class="eyebrow">READ NEXT</div><h2>Smart Reading Queue</h2><p>Prioritized from reading status, active project, PDF availability, and inactivity.</p></div><span class="pill blue">'+q.length+' queued</span></div><div class="reading-queue-list">'+(q.length?q.map((x,i)=>'<div class="reading-queue-row"><strong>0'+(i+1)+'</strong><div><b>'+esc(x.p.title)+'</b><small>'+esc(x.p.status)+' • '+(+x.p.readProgress||0)+'% read'+(x.p.pdfName?' • PDF ready':'')+'</small>'+prog(+x.p.readProgress||0)+'</div><div class="button-row compact">'+(x.p.pdfName?'<button class="mini-btn paper-open-btn" data-act="openPaperReader" data-id="'+x.p.id+'">Read</button>':'')+'<button class="mini-btn" data-act="openCitationManager" data-id="'+x.p.id+'">Cite</button></div></div>').join(''):'<div class="empty empty-compact">Reading queue is clear.</div>')+'</div></article>'}
function researchKnowledgeGraph(){
  const projects=S.projects.filter(p=>p.status==='active').slice(0,5),papers=S.researchPapers.filter(p=>p.projectId||S.researchNotes.some(n=>n.paperId===p.id)).slice(0,8),notes=S.researchNotes.filter(n=>n.paperId||n.projectId).slice(0,8);
  if(!projects.length&&!papers.length&&!notes.length)return'<div class="empty">Link papers and notes to projects to build the graph.</div>';
  const W=900,H=360,levels=[projects,papers,notes],ys=[60,180,300],nodes=new Map(),nodeHtml=[];
  levels.forEach((arr,li)=>arr.forEach((x,i)=>{const xPos=(i+1)*W/(arr.length+1),y=ys[li],key=(li===0?'project:':li===1?'paper:':'note:')+x.id;nodes.set(key,{x:xPos,y});nodeHtml.push('<g class="kg-node kg-'+(li===0?'project':li===1?'paper':'note')+'"><circle cx="'+xPos+'" cy="'+y+'" r="'+(li===1?18:15)+'"/><text x="'+xPos+'" y="'+(y+34)+'" text-anchor="middle">'+esc((x.title||'').slice(0,24))+'</text></g>')}));
  const edges=[];for(const p of papers){const a=nodes.get('paper:'+p.id),b=nodes.get('project:'+p.projectId);if(a&&b)edges.push('<line x1="'+a.x+'" y1="'+a.y+'" x2="'+b.x+'" y2="'+b.y+'"/>');for(const cid of (p.citedPaperIds||[])){const c=nodes.get('paper:'+cid);if(a&&c)edges.push('<line class="citation-edge" x1="'+a.x+'" y1="'+a.y+'" x2="'+c.x+'" y2="'+c.y+'"/>')}}for(const n of notes){const a=nodes.get('note:'+n.id),bp=nodes.get('paper:'+n.paperId),bj=nodes.get('project:'+n.projectId);if(a&&bp)edges.push('<line x1="'+a.x+'" y1="'+a.y+'" x2="'+bp.x+'" y2="'+bp.y+'"/>');else if(a&&bj)edges.push('<line x1="'+a.x+'" y1="'+a.y+'" x2="'+bj.x+'" y2="'+bj.y+'"/>')}
  return'<svg class="knowledge-graph" viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Research knowledge graph"><g class="kg-edges">'+edges.join('')+'</g>'+nodeHtml.join('')+'</svg><div class="kg-legend"><span class="project">Project</span><span class="paper">Paper</span><span class="note">Note</span></div>'
}
function researchKnowledgeGraphCard(){return'<article class="card knowledge-graph-card"><div class="card-head"><div><h2>Research Knowledge Graph</h2><p>Project → Paper → Note relationships generated from your links.</p></div></div>'+researchKnowledgeGraph()+'</article>'}
function researchPaperRow(p){
  const pr=S.projects.find(x=>x.id===p.projectId),hasPdf=!!p.pdfName;
  return'<div class="paper-row '+(hasPdf?'has-pdf':'')+'"><div class="paper-file-icon '+(hasPdf?'attached':'')+'">PDF</div><div class="growth-main"><div class="item-title">'+esc(p.title)+'</div><div class="item-meta">'+esc(p.authors||'Penulis belum diisi')+(p.year?' • '+esc(p.year):'')+(pr?' • '+esc(pr.title):'')+'</div><div class="paper-read-strip"><span>'+clamp(+p.readProgress||0,0,100)+'% read'+(p.lastPage?' • page '+p.lastPage:'')+(p.rating?' • ★ '+p.rating+'/5':'')+'</span>'+prog(+p.readProgress||0)+'</div>'+(hasPdf?'<div class="paper-attachment-meta"><span>PDF attached</span><b>'+esc(p.pdfName)+'</b><small>'+paperFileSize(p.pdfSize)+'</small></div>':'<div class="paper-attachment-meta empty-file"><span>No PDF attached</span></div>')+'<div class="tag-line">'+(p.tags||[]).map(t=>'<span>#'+esc(t)+'</span>').join('')+'</div></div><div class="paper-row-actions"><span class="pill '+(p.status==='key'?'green':p.status==='reading'?'orange':p.status==='read'?'blue':'')+'">'+esc(p.status)+'</span>'+(hasPdf?'<button class="mini-btn paper-open-btn" data-act="openPaperReader" data-id="'+p.id+'">Read</button>':'')+'<button class="mini-btn" data-act="openCitationManager" data-id="'+p.id+'">Cite</button>'+(hasPdf&&googleReady()?'<button class="mini-btn" data-act="syncPaperPDFToDrive" data-id="'+p.id+'">'+(p.driveFileId?'Drive ✓':'Sync Drive')+'</button>':'')+'<button class="mini-btn" data-act="inspectRelation" data-type="paper" data-id="'+p.id+'">Relations</button><button class="mini-btn" data-act="editResearchPaper" data-id="'+p.id+'">'+(hasPdf?'Edit':'Upload PDF')+'</button>'+(p.status==='read'?'<button class="mini-btn" data-act="archiveEntity" data-type="researchPaper" data-id="'+p.id+'" data-label="'+esc(p.title)+'">Archive</button>':'')+'</div></div>'
}
function researchPage(){
  const a=S.activities.filter(x=>x.category==='research').slice().reverse(),all=a.reduce((n,x)=>n+(+x.duration||0),0),papers=S.researchPapers.slice(),notes=S.researchNotes.slice().sort((x,y)=>(y.date||'').localeCompare(x.date||'')),reading=papers.filter(x=>x.status==='reading').length,avgProgress=papers.length?Math.round(papers.reduce((n,p)=>n+(+p.readProgress||0),0)/papers.length):0;
  $('#page').innerHTML=head('Research','Paper reader, citation manager, knowledge graph, research notes, and tracked research time.','<button class="btn btn-secondary" data-act="smartImportPaper">Import PDF</button><button class="btn btn-secondary" data-act="newResearchNote">+ Research Note</button><button class="btn btn-secondary" data-act="newResearchPaper">+ Paper</button><button class="btn btn-primary" data-act="addActivity" data-cat="research">+ Log Research</button>')+'<section class="grid metric-grid">'+metric('Research Time',mins(all),'All-time','◷')+metric('This Week',mins(catMin('research',7)),'Current week','▤')+metric('Papers',papers.length,reading+' currently reading','▦')+metric('Reading Progress',avgProgress+'%','Library average','◉')+metric('Research Notes',notes.length,'Linked knowledge','⌘')+'</section>'+consistencyCompact('research')+'<div class="grid two-col">'+readingQueueCard()+'<article class="card"><div class="card-head"><div><h2>Paper Library</h2><p>PDF, reading progress, citations, tags, and linked projects.</p></div></div><div class="growth-list">'+(papers.length?papers.map(researchPaperRow).join(''):'<div class="empty">Belum ada paper.</div>')+'</div></article></div>'+researchKnowledgeGraphCard()+'<div class="grid two-col section-gap"><article class="card"><div class="card-head"><div><h2>Research Log</h2><p>Notes can link directly to a paper or project.</p></div></div><div class="growth-list">'+(notes.length?notes.slice(0,14).map(n=>{const pr=S.projects.find(x=>x.id===n.projectId),pp=S.researchPapers.find(x=>x.id===n.paperId);return'<div class="research-note-row"><div class="growth-main"><div><span class="pill">'+esc(n.type)+'</span></div><div class="item-title">'+esc(n.title)+'</div><div class="item-meta">'+(n.date?fmt(n.date,{day:'numeric',month:'short'}):'')+(pr?' • '+esc(pr.title):'')+(pp?' • '+esc(pp.title):'')+'</div><small>'+esc((n.text||'').slice(0,180))+'</small></div><button class="mini-btn" data-act="editResearchNote" data-id="'+n.id+'">Edit</button></div>'}).join(''):'<div class="empty">Belum ada research note.</div>')+'</div></article><article class="card"><div class="card-head"><h2>Recent Research Work</h2></div><div class="timeline">'+(a.length?a.slice(0,12).map(x=>'<div class="timeline-item"><div class="item-main"><div class="item-title">'+esc(x.title)+'</div><div class="item-meta">'+fmt(x.date,{day:'numeric',month:'short'})+(x.startTime?' • '+x.startTime:'')+' • '+mins(x.duration)+' <span class="xp-pop">+'+activityXP(x)+' XP</span></div></div></div>').join(''):'<div class="empty">Belum ada sesi riset.</div>')+'</div></article></div>'
}
function dmathPlatformIcon(k){
  const s={
    instagram:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><rect x="4" y="4" width="16" height="16" rx="5"/><circle cx="12" cy="12" r="3.4"/><circle cx="17.3" cy="6.8" r=".8" fill="currentColor" stroke="none"/></svg>',
    youtube:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M20 8.2a3 3 0 0 0-2.1-2.1C16.3 5.7 14.4 5.5 12 5.5s-4.3.2-5.9.6A3 3 0 0 0 4 8.2c-.4 1.2-.5 2.4-.5 3.8s.1 2.6.5 3.8a3 3 0 0 0 2.1 2.1c1.6.4 3.5.6 5.9.6s4.3-.2 5.9-.6a3 3 0 0 0 2.1-2.1c.4-1.2.5-2.4.5-3.8s-.1-2.6-.5-3.8z"/><path d="m10 9 5 3-5 3z"/></svg>',
    facebook:'<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"><path d="M13.7 21v-8h2.7l.4-3h-3.1V8.1c0-.9.3-1.5 1.6-1.5H17V4a23 23 0 0 0-2.4-.1c-2.4 0-4.1 1.5-4.1 4.2V10H8v3h2.5v8z"/></svg>',
    website:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M3.8 12h16.4M12 3.5c2.3 2.4 3.5 5.2 3.5 8.5S14.3 18.1 12 20.5C9.7 18.1 8.5 15.3 8.5 12S9.7 5.9 12 3.5z"/></svg>'
  };return s[k]||routeIconSvg('dmath')
}
function dmathPreset(k){return DMATH_PRESETS[k]||{metric:'Metric',contentLabel:'Content',defaultFormat:'Post'}}
function dmathDefaultFormat(platform){return dmathPreset(platform).defaultFormat}
function dmathPct(p){return p.target>0?clamp((+p.current||0)/(+p.target||1)*100,0,100):0}
function dmathOverall(){const ps=['instagram','youtube','facebook','website'].map(k=>dmathPct(S.dmath[k]));return Math.round(ps.reduce((a,b)=>a+b,0)/ps.length)}
function dmathPlatformCard(k){const p=S.dmath[k],pct=dmathPct(p),remaining=Math.max(0,(+p.target||0)-(+p.current||0));return'<article class="card dmath-platform '+k+'"><div class="dmath-platform-head"><span class="dmath-platform-icon">'+dmathPlatformIcon(k)+'</span><div><h2>'+esc(p.name)+'</h2><p>'+esc(p.metric)+'</p></div><button class="mini-btn" data-act="editDMathPlatform" data-platform="'+k+'">Update '+esc(dmathPreset(k).metric)+'</button></div><div class="dmath-platform-value"><b>'+num(+p.current||0)+'</b><span>/ '+num(+p.target||0)+'</span></div>'+prog(pct)+'<div class="dmath-platform-foot"><span>'+Math.round(pct)+'% tercapai</span><b>'+num(remaining)+' lagi</b></div>'+(p.notes?'<div class="dmath-note">'+esc(p.notes)+'</div>':'')+'</article>'}
function dmathPlatformForm(k){const p=S.dmath[k],preset=dmathPreset(k),metric=preset.metric;return'<form id="dmathPlatformForm"><div class="smart-form-summary"><span class="dmath-platform-icon large">'+dmathPlatformIcon(k)+'</span><div><b>'+esc(p.name)+'</b><small>Metric otomatis · '+esc(metric)+'</small></div></div><div class="form-grid"><div class="field"><label>'+esc(metric)+' saat ini</label><input name="current" type="number" min="0" step="1" inputmode="numeric" value="'+(+p.current||0)+'"></div><div class="field"><label>Target '+esc(metric)+'</label><input name="target" type="number" min="1" step="1" inputmode="numeric" value="'+(+p.target||1)+'"></div><div class="field full"><label>Target '+esc(preset.contentLabel)+' per bulan</label><input name="monthlyTarget" type="number" min="0" step="1" inputmode="numeric" value="'+(+p.monthlyTarget||0)+'" placeholder="Opsional"></div><details class="field full smart-optional"><summary>Catatan strategi <span>Opsional</span></summary><textarea name="notes" rows="3" placeholder="Tambahkan hanya jika diperlukan">'+esc(p.notes||'')+'</textarea></details></div><input type="hidden" name="platform" value="'+k+'"><button class="btn btn-primary" style="margin-top:14px;width:100%">Simpan '+esc(p.name)+'</button></form>'}
function openDMathPlatform(k){if(!S.dmath[k])return;open('<div class="modal-head"><div><div class="eyebrow">DMATH LEARNING</div><h2 id="modalTitle">Update '+esc(S.dmath[k].name)+'</h2></div><button class="icon-btn" data-act="close">×</button></div>'+dmathPlatformForm(k))}
function dmathContentStatusLabel(s){return{idea:'Idea',draft:'Draft',production:'Production',scheduled:'Scheduled',published:'Published'}[s]||s}
function dmathContentForm(x={}){
  const edit=!!x.id,platform=x.platform||'instagram',defaultFormat=x.format||dmathDefaultFormat(platform);
  const advanced='<div class="form-grid"><div class="field"><label>Format</label><select name="format"><option value="auto" '+(!edit?'selected':'')+'>Auto dari platform</option>'+['Carousel','Reels','Shorts','Video','Story','Post','Article','Website Update','Live','Other'].map(v=>'<option '+(edit&&defaultFormat===v?'selected':'')+'>'+v+'</option>').join('')+'</select></div><div class="field"><label>Status</label><select name="status">'+['idea','draft','production','scheduled','published'].map(s=>'<option value="'+s+'" '+((x.status||'idea')===s?'selected':'')+'>'+dmathContentStatusLabel(s)+'</option>').join('')+'</select></div><div class="field"><label>Jadwal publish</label><input name="scheduledDate" type="date" value="'+esc(x.scheduledDate||'')+'"></div><div class="field"><label>Tanggal published</label><input name="publishedDate" type="date" value="'+esc(x.publishedDate||'')+'"></div><div class="field full"><label>URL</label><input name="url" type="url" value="'+esc(x.url||'')+'" placeholder="Opsional"></div><div class="field full"><label>Catatan</label><textarea name="notes" rows="3">'+esc(x.notes||'')+'</textarea></div></div>';
  return'<form id="dmathContentForm" class="smart-minimal-form"><div class="field"><label>Judul konten</label><input name="title" required autofocus value="'+esc(x.title||'')+'" placeholder="Contoh: Integral Riemann untuk pemula"></div><div class="field"><label>Platform</label><select name="platform">'+['instagram','youtube','facebook','website'].map(k=>'<option value="'+k+'" '+(platform===k?'selected':'')+'>'+esc(S.dmath[k].name)+'</option>').join('')+'</select></div>'+autoSummaryLine(['Format otomatis',dmathContentStatusLabel(x.status||'idea'),'Tanggal diisi saat Scheduled/Published'])+smartAdvanced(advanced,edit)+'<input type="hidden" name="id" value="'+(x.id||'')+'"><button class="btn btn-primary smart-submit">Simpan Konten</button></form>'
}
function openDMathContent(x=null){open('<div class="modal-head"><div><div class="eyebrow">DMATH CONTENT</div><h2 id="modalTitle">'+(x?'Edit Content':'Content Baru')+'</h2></div><button class="icon-btn" data-act="close">×</button></div>'+dmathContentForm(x||{})+trashDeleteButton('dmathContent',x,x?.title))}
