  {min:24,name:'Master',mark:'III',key:'disciplined'},
  {min:38,name:'Grandmaster',mark:'IV',key:'diligent'},
  {min:54,name:'Epic',mark:'V',key:'driven'},
  {min:70,name:'Legend',mark:'VI',key:'elite'},
  {min:84,name:'Mythic',mark:'VII',key:'master'},
  {min:95,name:'Immortal',mark:'VIII',key:'legend'}
