function automationSettingsCard(){
  const log=S.automationLog.slice().reverse().slice(0,6);
  const row=(id,label,desc,value)=>'<div class="automation-setting-row"><div><b>'+label+'</b><small>'+desc+'</small></div><select id="'+id+'"><option value="true" '+(value?'selected':'')+'>Aktif</option><option value="false" '+(!value?'selected':'')+'>Off</option></select></div>';
  return'<article class="card automation-settings-card"><div class="card-head"><div><div class="eyebrow">AUTOMATION ENGINE</div><h2>Otomasi Desca OS</h2><p>Rule aman berjalan lokal dan dibuat idempotent agar tidak menghasilkan task duplikat.</p></div><span class="pill '+(S.settings.automationEnabled?'green':'')+'">'+(S.settings.automationEnabled?'ON':'OFF')+'</span></div><div class="automation-settings-list">'+row('sautoengine','Automation Engine','Master switch seluruh rule otomatis.',S.settings.automationEnabled)+row('sautoautoplan','Auto-plan harian','Task tanpa jam otomatis ditempatkan ke slot kosong dan menghindari agenda Google.',S.settings.automationAutoPlan)+row('sautodeadline','Deadline escalation','Task deadline dekat otomatis menjadi High Priority.',S.settings.automationDeadline)+row('sautocalprep','Calendar preparation','Agenda penting besok dapat task persiapan otomatis.',S.settings.automationCalendarPrep)+row('sautos2','S2 weekly next step','Sabtu memilih next step S2 yang belum selesai.',S.settings.automationS2)+row('sautoresearch','Research nudge','Jika riset kosong beberapa hari, buat satu nudge terukur.',S.settings.automationResearchNudge)+'</div>'+(log.length?'<div class="automation-log"><div class="brief-section-title"><b>Aktivitas Otomasi Terbaru</b><span>'+log.length+' log</span></div>'+log.map(x=>'<div class="automation-log-row"><span>'+esc(x.rule)+'</span><b>'+esc(x.summary)+'</b><small>'+esc(x.date)+'</small></div>').join('')+'</div>':'<div class="empty empty-compact" style="margin-top:12px">Belum ada rule yang menghasilkan tindakan.</div>')+'<div class="button-row" style="margin-top:12px"><button class="btn btn-primary" data-act="runAutomations">Jalankan Sekarang</button></div></article>'
}
