function searchItems(q=''){
  const term=q.trim().toLowerCase();if(!term)return[];let out=[],match=(...vals)=>vals.filter(Boolean).join(' ').toLowerCase().includes(term),push=(x)=>out.push(x);
  for(const t of S.tasks)if(match(t.title,t.notes,(t.tags||[]).join(' ')))push({type:'Task',title:t.title,meta:(t.date||'Inbox')+' • '+cat(t.category),route:'tasks'});
  for(const r of S.routines)if(match(r.title,cat(r.category)))push({type:'Routine',title:r.title,meta:(r.time||'Flexible')+' • '+cat(r.category),route:'life'});
  for(const a of S.activities)if(match(a.title,a.notes,cat(a.category)))push({type:'Activity',title:a.title,meta:a.date+' • '+cat(a.category)+' • '+mins(a.duration),route:a.category==='study'?'study':a.category==='research'?'research':a.category==='dmath'?'dmath':a.category==='quran'?'quran':a.category==='health'?'health':'timeline'});
  for(const r of (S.runs||[]))if(match(r.title,runTypeLabel(r.type),r.distanceKm+'km',r.shoe,r.surface,r.notes))push({type:'Run',title:r.title||runTypeLabel(r.type),meta:r.date+' • '+r.distanceKm.toFixed(2)+' km • '+runPaceText(runPaceSec(r)),route:'running'});
  for(const e of (S.quran?.entries||[])){const label=quranPlainLabel(e);if(match(label,e.notes,e.juz))push({type:'Quran',title:label,meta:(e.status||'new')+' • '+clamp(+e.mastery||0,0,100)+'% mastery',route:'quran'})}
  for(const g of S.goals)if(match(g.title,g.area,(g.milestones||[]).join(' ')))push({type:'Goal',title:g.title,meta:(g.area||'Goal')+' • '+(g.progress||0)+'% • '+goalForecast(g).status,route:'goals'});
  for(const x of (S.s2Prep?.checklist||[]))if(match(x.title,'S2',x.group))push({type:'S2 Prep',title:x.title,meta:(x.group||'General')+(x.due?' • '+x.due:''),route:'goals'});
  for(const x of (S.s2Prep?.documents||[]))if(match(x.title,'S2 document',x.group))push({type:'S2 Document',title:x.title,meta:(x.group||'Other')+(x.vaultDocumentId?' • Vault ✓':''),route:x.vaultDocumentId?'vault':'goals'});
  for(const x of [...(S.s2Prep?.universities||[]),...(S.s2Prep?.scholarships||[])])if(match(x.name,x.program,x.status,'S2'))push({type:'S2 Application',title:x.name,meta:s2StageLabel(x.status)+(x.deadline?' • '+x.deadline:''),route:'goals'});
  for(const p of S.projects)if(match(p.title,p.area,p.nextAction,p.notes))push({type:'Project',title:p.title,meta:projectHealth(p).status+' • '+projectProgress(p)+'%',route:'projects'});
  for(const t of S.studyTopics)if(match(t.title,t.subject,t.notes))push({type:'Study Topic',title:t.title,meta:(t.subject||'General')+' • '+t.mastery+'% mastery',route:'study'});
  for(const p of S.researchPapers)if(match(p.title,p.authors,p.doi,(p.tags||[]).join(' '),p.notes,p.annotations,(p.paperMarks||[]).map(m=>(m.quote||'')+' '+(m.text||'')).join(' '),p.pdfName))push({type:'Paper',title:p.title,meta:(p.status||'to-read')+' • '+(+p.readProgress||0)+'% read'+(p.pdfName?' • PDF':''),route:'research'});
  for(const n of S.researchNotes)if(match(n.title,n.text,n.type))push({type:'Research Note',title:n.title,meta:(n.type||'idea')+(n.date?' • '+n.date:''),route:'research'});
  for(const c of (S.dmath?.content||[]))if(match(c.title,c.format,c.platform,c.notes,c.status))push({type:'DMath Content',title:c.title,meta:dmathContentStatusLabel(c.status)+' • '+(S.dmath[c.platform]?.name||c.platform),route:'dmath'});
  if(!S.settings.vaultLockEnabled||vaultUnlockedSession)for(const v of (S.vault||[]))if(match(v.title,v.category,v.fileName,v.notes))push({type:'Vault Document',title:v.title,meta:(v.category||'Other')+' • '+(v.driveFileId?'Drive synced':'Local'),route:'vault'});
  for(const sem of S.academic.semesters)if(match(sem.name,sem.status))push({type:'Semester',title:sem.name,meta:sem.status,route:'academic'});
  for(const c of S.academic.courses)if(match(c.name,c.lecturer,c.category,c.grade))push({type:'Course',title:c.name,meta:(c.grade||'Not graded')+' • '+c.credits+' SKS',route:'academic'});
  for(const a of S.academic.assessments)if(match(a.title,S.academic.courses.find(c=>c.id===a.courseId)?.name))push({type:'Assessment',title:a.title,meta:a.date,route:'academic'});
  for(const m of S.examModes)if(match(m.title,m.notes,cat(m.category)))push({type:'Focus Mode',title:m.title,meta:m.date+' • '+cat(m.category),route:'academic'});
  for(const a of S.archive)if(match(a.label,a.entityType))push({type:'Archive',title:a.label,meta:a.entityType+' • archived',route:'recovery'});
  for(const n of S.notes)if(match(n.text))push({type:'Note',title:n.text.slice(0,90),meta:n.date,route:'inbox'});
  for(const [d,j] of Object.entries(S.journal))if(match(...Object.values(j||{})))push({type:'Journal',title:(j.l||j.a||j.t||'Journal entry').slice(0,90),meta:d,route:'journal'});
  return out.slice(0,30)
}
