  const advanced='<div class="form-grid"><div class="field"><label>Area <span class="field-auto">auto jika kosong</span></label><input name="area" list="goalAreaOptions" value="'+esc(area)+'" placeholder="Otomatis dari nama goal">'+suggestionList('goalAreaOptions',GOAL_AREAS)+'</div><div class="field"><label>Deadline</label><input name="deadline" type="date" value="'+deadline+'"></div><div class="field"><label>Status</label><select name="status">'+['active','paused','completed'].map(s=>'<option value="'+s+'" '+((g.status||'active')===s?'selected':'')+'>'+s+'</option>').join('')+'</select></div><div class="field"><label>Progress</label><select name="autoProgress"><option value="true" '+(g.autoProgress!==false?'selected':'')+'>Otomatis</option><option value="false" '+(g.autoProgress===false?'selected':'')+'>Manual</option></select></div><div class="field"><label>Manual progress (%)</label><input name="progress" type="number" min="0" max="100" value="'+clamp(+g.progress||0,0,100)+'"></div><div class="field full"><label>Milestones</label><textarea name="milestones" rows="5" placeholder="Satu milestone per baris">'+esc(ms)+'</textarea></div></div>';
