function normalizeDoi(raw=''){return String(raw||'').trim().replace(/^https?:\/\/(?:dx\.)?doi\.org\//i,'').replace(/^doi:\s*/i,'').trim()}
function crossrefDoiPath(doi){return normalizeDoi(doi).split('/').map(x=>encodeURIComponent(x)).join('/')}
async function importPaperMetadata(){
  const form=$('#researchPaperForm');if(!form)return;
  const raw=form.elements.doi?.value||form.elements.url?.value||'',doi=normalizeDoi(raw);
  if(!doi){toast('Masukkan DOI atau link doi.org');return}
  const btn=form.querySelector('[data-act="importPaperMeta"]');if(btn){btn.disabled=true;btn.textContent='Mengambil...'}
  try{
    const res=await fetch('https://api.crossref.org/v1/works/'+crossrefDoiPath(doi));
    if(!res.ok)throw new Error('Metadata DOI tidak ditemukan');
    const json=await res.json(),m=json?.message||{},title=(m.title||[])[0]||'',authors=(m.author||[]).map(a=>[a.given,a.family].filter(Boolean).join(' ')).filter(Boolean).join(', '),year=String(m.published?.['date-parts']?.[0]?.[0]||m.issued?.['date-parts']?.[0]?.[0]||''),url=m.URL||('https://doi.org/'+doi),tags=(m.subject||[]).slice(0,6).join(', ');
    if(form.elements.title&&title)form.elements.title.value=title;
    if(form.elements.authors&&authors)form.elements.authors.value=authors;
    if(form.elements.year&&year)form.elements.year.value=year;
    if(form.elements.doi)form.elements.doi.value=doi;
    if(form.elements.url)form.elements.url.value=url;
    if(form.elements.tags&&tags)form.elements.tags.value=tags;
    const projectId=inferProjectId(title||form.elements.title?.value||'','__auto__');if(projectId&&form.elements.projectId)form.elements.projectId.value=projectId;
    toast('Metadata paper berhasil diambil')
  }catch(err){toast('Import DOI gagal: '+(err?.message||err))}
  finally{if(btn){btn.disabled=false;btn.textContent='Ambil Metadata'}}
}
function paperFilesDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('desca-os-paper-files-v1',2);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains('files'))db.createObjectStore('files',{keyPath:'paperId'});if(!db.objectStoreNames.contains('vault'))db.createObjectStore('vault',{keyPath:'documentId'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function paperFilePut(paperId,file){
  if(!paperId||!file)throw new Error('Paper atau file tidak valid');
  const isPdf=file.type==='application/pdf'||/\.pdf$/i.test(file.name||'');
  if(!isPdf)throw new Error('File harus berformat PDF');
  if(file.size>50*1024*1024)throw new Error('Ukuran PDF maksimal 50 MB');
  const db=await paperFilesDB(),tx=db.transaction('files','readwrite');
  tx.objectStore('files').put({paperId,name:file.name||'paper.pdf',type:file.type||'application/pdf',size:file.size||0,updatedAt:new Date().toISOString(),blob:file});
  await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error||new Error('Upload PDF dibatalkan'))});
  return true
}
async function paperFileGet(paperId){
  try{const db=await paperFilesDB(),tx=db.transaction('files','readonly');return await new Promise((res,rej)=>{const q=tx.objectStore('files').get(paperId);q.onsuccess=()=>res(q.result||null);q.onerror=()=>rej(q.error)})}catch{return null}
}
async function paperFileDelete(paperId){
  try{const db=await paperFilesDB(),tx=db.transaction('files','readwrite');tx.objectStore('files').delete(paperId);await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});return true}catch{return false}
}
async function vaultFilePut(documentId,file){
  if(!documentId||!file)throw new Error('Document atau file tidak valid');
  if(file.size>100*1024*1024)throw new Error('Ukuran file maksimal 100 MB');
  const db=await paperFilesDB(),tx=db.transaction('vault','readwrite');
  tx.objectStore('vault').put({documentId,name:file.name||'document',type:file.type||'application/octet-stream',size:file.size||0,updatedAt:new Date().toISOString(),blob:file});
  await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error);tx.onabort=()=>rej(tx.error||new Error('Upload dibatalkan'))});return true
}
async function vaultFileGet(documentId){try{const db=await paperFilesDB(),tx=db.transaction('vault','readonly');return await new Promise((res,rej)=>{const q=tx.objectStore('vault').get(documentId);q.onsuccess=()=>res(q.result||null);q.onerror=()=>rej(q.error)})}catch{return null}}
async function vaultFileDelete(documentId){try{const db=await paperFilesDB(),tx=db.transaction('vault','readwrite');tx.objectStore('vault').delete(documentId);await new Promise((res,rej)=>{tx.oncomplete=res;tx.onerror=()=>rej(tx.error)});return true}catch{return false}}
async function openVaultFile(id){const v=S.vault.find(x=>x.id===id);if(!v)return;let row=await vaultFileGet(id);if(!row?.blob&&v.driveFileId&&googleReady()){await restoreVaultFromDrive(id,true);row=await vaultFileGet(id)}if(!row?.blob){toast('File tidak ditemukan di browser ini');return}const url=URL.createObjectURL(row.blob),w=window.open(url,'_blank','noopener');if(!w){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click()}setTimeout(()=>URL.revokeObjectURL(url),60000)}
async function syncVaultToDrive(id){const v=S.vault.find(x=>x.id===id);if(!v)return;if(!googleReady()){toast('Connect Google first');return}const row=await vaultFileGet(id);if(!row?.blob){toast('Local file not found');return}try{const name='desca-vault-'+id+'-'+(v.fileName||'document').replace(/[^A-Za-z0-9._-]+/g,'_'),existing=v.driveFileId?{id:v.driveFileId}:await driveAppDataFind(name),remote=await driveAppDataUpload(name,row.blob,row.type||'application/octet-stream',existing?.id||'');v.driveFileId=remote.id;v.driveSyncedAt=new Date().toISOString();save('Sync vault file');toast('Document synced to Google Drive');render()}catch(e){toast('Drive sync failed: '+googleFriendlyError(e))}}
async function restoreVaultFromDrive(id,silent=false){const v=S.vault.find(x=>x.id===id);if(!v)return false;if(!googleReady()){if(!silent)toast('Connect Google first');return false}try{let remote=v.driveFileId?{id:v.driveFileId}:null;if(!remote){if(!silent)toast('No Drive copy linked');return false}const blob=await driveAppDataDownload(remote.id),file=new File([blob],v.fileName||'document',{type:v.fileType||blob.type||'application/octet-stream'});await vaultFilePut(id,file);v.fileSize=file.size;v.fileType=file.type;v.driveSyncedAt=new Date().toISOString();save('Restore vault file');if(!silent){toast('Document restored from Drive');render()}return true}catch(e){if(!silent)toast('Drive restore failed: '+googleFriendlyError(e));return false}}

function paperFileSize(v){const n=Math.max(0,+v||0);return n>=1048576?(n/1048576).toFixed(n>=10485760?0:1)+' MB':n>=1024?Math.round(n/1024)+' KB':n+' B'}
async function openPaperPDF(id){
  const p=S.researchPapers.find(x=>x.id===id);if(!p)return;
  const row=await paperFileGet(id);
  if(!row?.blob){toast('File PDF tidak ditemukan di browser ini');return}
  const url=URL.createObjectURL(row.blob),w=window.open(url,'_blank','noopener');
  if(!w){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click()}
  setTimeout(()=>URL.revokeObjectURL(url),60000)
}
async function removePaperPDF(id){
  const p=S.researchPapers.find(x=>x.id===id);if(!p)return;
  if(!confirm('Hapus PDF dari Paper Library? Metadata paper tetap disimpan.'))return;
  await paperFileDelete(id);p.pdfName='';p.pdfSize=0;p.pdfType='';p.pdfAttachedAt='';save('Remove paper PDF');toast('PDF dihapus');close();render()
}
async function saveResearchPaperForm(form,d){
  const old=S.researchPapers.find(x=>x.id===d.id),title=d.title.trim(),id=d.id||uid('paper'),file=form.elements.pdfFile?.files?.[0]||null;
  if(file&&!(file.type==='application/pdf'||/\.pdf$/i.test(file.name||''))){toast('File harus PDF');return}
  if(file&&file.size>50*1024*1024){toast('PDF maksimal 50 MB');return}
  const v={id,title,authors:(d.authors||'').trim(),year:(d.year||'').trim(),status:d.status||'to-read',doi:(d.doi||'').trim(),url:(d.url||'').trim(),projectId:inferProjectId(title,d.projectId||old?.projectId||''),tags:(d.tags||'').split(',').map(x=>x.trim()).filter(Boolean),notes:(d.notes||'').trim(),annotations:old?.annotations||'',paperMarks:Array.isArray(old?.paperMarks)?old.paperMarks:[],citedPaperIds:Array.from(form.querySelector('[name="citedPaperIds"]')?.selectedOptions||[]).map(o=>o.value),readProgress:clamp(+old?.readProgress||0,0,100),lastPage:Math.max(0,+old?.lastPage||0),rating:clamp(+old?.rating||0,0,5),lastOpenedAt:old?.lastOpenedAt||'',pdfName:old?.pdfName||'',pdfSize:+old?.pdfSize||0,pdfType:old?.pdfType||'',pdfAttachedAt:old?.pdfAttachedAt||'',driveFileId:old?.driveFileId||'',driveSyncedAt:old?.driveSyncedAt||'',createdAt:old?.createdAt||new Date().toISOString()};
  try{
    if(file){await paperFilePut(id,file);v.pdfName=file.name||'paper.pdf';v.pdfSize=file.size||0;v.pdfType=file.type||'application/pdf';v.pdfAttachedAt=new Date().toISOString()}
    old?Object.assign(old,v):S.researchPapers.push(v);save(old?'Update paper':'New paper');close();toast((old?'Paper diperbarui':'Paper ditambahkan')+(file?' · PDF attached':''));render()
  }catch(err){toast('Upload PDF gagal: '+(err?.message||err))}
}
